args.source:
import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "stable-plugin",
  name: "Stable Plugin",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "tool",
      tool: {
        name: "stable_value",
        version: "1.0.0",
        description: "Returns the stable value 18.",
        permissions: [],
        sideEffect: false,
        parameters: {
          type: "object",
          properties: {},
          additionalProperties: false,
        },
        outputSchema: {
          type: "object",
          properties: {
            ok: { type: "boolean" },
            data: { type: "number" },
          },
          required: ["ok", "data"],
        },
        async handler(args, tctx) {
          return { ok: true, data: 18 };
        },
      },
    });
  },
};

export default plugin;

